-- New application baseline only. For existing DBs, write incremental migrations.
-- Shared SaaS: application sets SET LOCAL app.tenant_id = '<server-verified tenant UUID/text>' within each transaction.
-- Row-level security is intentionally enabled and forced on all tenant-bound tables below.
CREATE TABLE IF NOT EXISTS tenants (id TEXT PRIMARY KEY, name TEXT NOT NULL, deployment_mode TEXT NOT NULL CHECK (deployment_mode IN ('customer_hosted','managed_single_tenant','shared_saas')), active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS app_users (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), email TEXT, mobile TEXT, display_name TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('pending','active','suspended','deactivated')), locale TEXT NOT NULL DEFAULT 'en', created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(tenant_id,email), UNIQUE(tenant_id,mobile), UNIQUE(tenant_id,id));
CREATE TABLE IF NOT EXISTS roles (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), code TEXT NOT NULL, name TEXT NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE, UNIQUE(tenant_id,code), UNIQUE(tenant_id,id));
CREATE TABLE IF NOT EXISTS role_permissions (tenant_id TEXT NOT NULL REFERENCES tenants(id), role_id TEXT NOT NULL, feature_code TEXT NOT NULL, action TEXT NOT NULL CHECK(action IN ('view','create','edit','delete','approve','export','manage')), PRIMARY KEY(tenant_id,role_id,feature_code,action), FOREIGN KEY(tenant_id,role_id) REFERENCES roles(tenant_id,id));
CREATE TABLE IF NOT EXISTS user_role_assignments (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), user_id TEXT NOT NULL, role_id TEXT NOT NULL, function_code TEXT NOT NULL DEFAULT '*', active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(tenant_id,user_id,role_id,function_code), FOREIGN KEY(tenant_id,user_id) REFERENCES app_users(tenant_id,id), FOREIGN KEY(tenant_id,role_id) REFERENCES roles(tenant_id,id));
CREATE TABLE IF NOT EXISTS geography_nodes (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), parent_id TEXT, level TEXT NOT NULL, name TEXT NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE, UNIQUE(tenant_id,level,id), UNIQUE(tenant_id,id), FOREIGN KEY(tenant_id,parent_id) REFERENCES geography_nodes(tenant_id,id));
CREATE TABLE IF NOT EXISTS user_geography_scopes (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), user_id TEXT NOT NULL, geography_id TEXT NOT NULL, function_code TEXT NOT NULL DEFAULT '*', active BOOLEAN NOT NULL DEFAULT TRUE, UNIQUE(tenant_id,user_id,geography_id,function_code), FOREIGN KEY(tenant_id,user_id) REFERENCES app_users(tenant_id,id), FOREIGN KEY(tenant_id,geography_id) REFERENCES geography_nodes(tenant_id,id));
CREATE TABLE IF NOT EXISTS approval_requests (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), entity_type TEXT NOT NULL, entity_id TEXT NOT NULL, maker_id TEXT NOT NULL REFERENCES app_users(id), reviewer_id TEXT REFERENCES app_users(id), status TEXT NOT NULL CHECK(status IN ('pending','approved','rejected','change_requested','cancelled')), version INTEGER NOT NULL DEFAULT 1, payload JSONB NOT NULL DEFAULT '{}'::jsonb, submitted_at TIMESTAMPTZ NOT NULL DEFAULT now(), reviewed_at TIMESTAMPTZ, CHECK(reviewer_id IS NULL OR reviewer_id <> maker_id));
CREATE TABLE IF NOT EXISTS notification_templates (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), code TEXT NOT NULL, channel TEXT NOT NULL CHECK(channel IN ('email','sms','whatsapp','push','in_app')), locale TEXT NOT NULL DEFAULT 'en', body TEXT NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE, UNIQUE(tenant_id,code,channel,locale));
CREATE TABLE IF NOT EXISTS notification_preferences (tenant_id TEXT NOT NULL REFERENCES tenants(id), user_id TEXT NOT NULL REFERENCES app_users(id), channel TEXT NOT NULL, consent BOOLEAN NOT NULL DEFAULT FALSE, enabled BOOLEAN NOT NULL DEFAULT TRUE, PRIMARY KEY(tenant_id,user_id,channel));
CREATE TABLE IF NOT EXISTS notification_outbox (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), user_id TEXT NOT NULL REFERENCES app_users(id), channel TEXT NOT NULL, payload JSONB NOT NULL, status TEXT NOT NULL DEFAULT 'pending', attempts INTEGER NOT NULL DEFAULT 0, next_attempt_at TIMESTAMPTZ, provider_ref TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(tenant_id,id));
CREATE TABLE IF NOT EXISTS survey_forms (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), title TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'draft', current_version INTEGER NOT NULL DEFAULT 1, opens_at TIMESTAMPTZ, closes_at TIMESTAMPTZ, require_location BOOLEAN NOT NULL DEFAULT FALSE, submission_mode TEXT NOT NULL DEFAULT 'once');
CREATE TABLE IF NOT EXISTS survey_form_versions (form_id TEXT NOT NULL REFERENCES survey_forms(id), tenant_id TEXT NOT NULL REFERENCES tenants(id), version INTEGER NOT NULL, definition JSONB NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), PRIMARY KEY(form_id,version));
CREATE TABLE IF NOT EXISTS survey_targets (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), form_id TEXT NOT NULL REFERENCES survey_forms(id), target_type TEXT NOT NULL CHECK(target_type IN ('user','role','geography')), target_id TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS survey_submissions (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), form_id TEXT NOT NULL REFERENCES survey_forms(id), form_version INTEGER NOT NULL, actor_id TEXT NOT NULL REFERENCES app_users(id), geography_id TEXT REFERENCES geography_nodes(id), answers JSONB NOT NULL, latitude DOUBLE PRECISION, longitude DOUBLE PRECISION, accuracy_m DOUBLE PRECISION, captured_at TIMESTAMPTZ, location_mocked BOOLEAN, submitted_at TIMESTAMPTZ NOT NULL DEFAULT now(), CHECK(latitude IS NULL OR latitude BETWEEN -90 AND 90), CHECK(longitude IS NULL OR longitude BETWEEN -180 AND 180));
CREATE TABLE IF NOT EXISTS cms_items (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), author_id TEXT NOT NULL REFERENCES app_users(id), category TEXT NOT NULL, locale TEXT NOT NULL, title TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'draft', version INTEGER NOT NULL DEFAULT 1, payload JSONB NOT NULL DEFAULT '{}'::jsonb, approved_by TEXT REFERENCES app_users(id), published_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS report_definitions (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), code TEXT NOT NULL, name TEXT NOT NULL, definition JSONB NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE, UNIQUE(tenant_id,code));
CREATE TABLE IF NOT EXISTS audit_events (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), actor_id TEXT, action TEXT NOT NULL, resource TEXT NOT NULL, resource_id TEXT, outcome TEXT NOT NULL, correlation_id TEXT NOT NULL, metadata JSONB NOT NULL DEFAULT '{}'::jsonb, latitude DOUBLE PRECISION, longitude DOUBLE PRECISION, occurred_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS feature_flags (tenant_id TEXT NOT NULL REFERENCES tenants(id), code TEXT NOT NULL, enabled BOOLEAN NOT NULL DEFAULT FALSE, PRIMARY KEY(tenant_id,code));
CREATE TABLE IF NOT EXISTS app_releases (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), platform TEXT NOT NULL, version_name TEXT NOT NULL, version_code INTEGER NOT NULL, url TEXT NOT NULL, sha256 TEXT NOT NULL, mandatory BOOLEAN NOT NULL DEFAULT FALSE, enabled BOOLEAN NOT NULL DEFAULT TRUE, UNIQUE(tenant_id,platform,version_code));
CREATE TABLE IF NOT EXISTS commerce_rules (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), kind TEXT NOT NULL CHECK(kind IN ('pricing','discount','tax')), scope TEXT NOT NULL, target_id TEXT, config JSONB NOT NULL, priority INTEGER NOT NULL DEFAULT 0, valid_from TIMESTAMPTZ, valid_to TIMESTAMPTZ, active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS payment_webhook_events (tenant_id TEXT NOT NULL REFERENCES tenants(id), provider TEXT NOT NULL, event_id TEXT NOT NULL, status TEXT NOT NULL, received_at TIMESTAMPTZ NOT NULL DEFAULT now(), PRIMARY KEY(tenant_id,provider,event_id));
CREATE INDEX IF NOT EXISTS idx_app_users_tenant_status ON app_users(tenant_id,status);
CREATE INDEX IF NOT EXISTS idx_assignments_user_active ON user_role_assignments(tenant_id,user_id,active);
CREATE INDEX IF NOT EXISTS idx_geo_parent ON geography_nodes(tenant_id,parent_id);
CREATE INDEX IF NOT EXISTS idx_scope_user ON user_geography_scopes(tenant_id,user_id,active);
CREATE INDEX IF NOT EXISTS idx_approvals_pending ON approval_requests(tenant_id,status,submitted_at);
CREATE INDEX IF NOT EXISTS idx_outbox_claim ON notification_outbox(tenant_id,status,next_attempt_at);
CREATE INDEX IF NOT EXISTS idx_survey_form_time ON survey_forms(tenant_id,status,opens_at,closes_at);
CREATE INDEX IF NOT EXISTS idx_survey_actor ON survey_submissions(tenant_id,actor_id,form_id);
CREATE INDEX IF NOT EXISTS idx_cms_published ON cms_items(tenant_id,status,locale,category);
CREATE INDEX IF NOT EXISTS idx_audit_tenant_time ON audit_events(tenant_id,occurred_at DESC);
CREATE INDEX IF NOT EXISTS idx_rules_tenant_scope ON commerce_rules(tenant_id,kind,scope,active);
-- RLS only protects row reads/writes when the app reliably sets a server-verified tenant ID.
DO $rls$ DECLARE tbl TEXT; BEGIN
 FOREACH tbl IN ARRAY ARRAY['app_users','roles','role_permissions','user_role_assignments','geography_nodes','user_geography_scopes','approval_requests','notification_templates','notification_preferences','notification_outbox','survey_forms','survey_form_versions','survey_targets','survey_submissions','cms_items','report_definitions','audit_events','feature_flags','app_releases','commerce_rules','payment_webhook_events'] LOOP
  EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',tbl);
  EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY',tbl);
  EXECUTE format('CREATE POLICY tenant_isolation ON %I USING (tenant_id = current_setting(''app.tenant_id'', true)) WITH CHECK (tenant_id = current_setting(''app.tenant_id'', true))',tbl);
 END LOOP;
END $rls$;
